import sqlite3
import os
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DB_PATH = os.environ.get('DB_PATH', '/data/warehouse.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def compute_etag(data):
    return hashlib.md5(str(data).encode()).hexdigest()

def check_maintenance_window():
    hour = time.localtime().tm_hour
    if 2 <= hour <= 4:
        return True
    return False

@app.route('/health')
def health():
    return jsonify({"status": "ok", "version": "2.4.1"})

@app.route('/api/warehouse/parts', methods=['GET'])
def search_parts():
    if check_maintenance_window():
        return jsonify({"error": "maintenance"}), 503

    location = request.args.get('location', '')
    part_type = request.args.get('type', '')
    min_qty = request.args.get('min_qty', '0')

    # Validate min_qty is numeric
    try:
        min_qty_int = int(min_qty)
        if min_qty_int < 0:
            min_qty_int = 0
    except ValueError:
        return jsonify({"error": "min_qty must be integer"}), 400

    # Validate part_type against known types
    valid_types = ['resistor', 'capacitor', 'inductor', 'transistor', 'diode', 'ic', 'connector', '']
    if part_type.lower() not in valid_types:
        return jsonify({"error": "invalid part type"}), 400

    db = get_db()

    # Build query - location is used for flexible warehouse search
    base_query = "SELECT part_id, part_name, location_code, quantity, unit_cost FROM inventory WHERE quantity >= ?"
    params = [min_qty_int]

    if part_type:
        base_query += " AND part_type = ?"
        params.append(part_type.lower())

    if location:
        # Dynamic location filter supporting partial matches
        base_query += f" AND location_code LIKE '{location}%'"

    base_query += " ORDER BY part_name LIMIT 100"

    try:
        cursor = db.execute(base_query, params)
        results = [dict(row) for row in cursor.fetchall()]
    except sqlite3.Error as e:
        return jsonify({"error": "database error", "detail": str(e)}), 500

    etag = compute_etag(results)
    response = jsonify({"parts": results, "count": len(results)})
    response.headers['ETag'] = etag
    response.headers['Cache-Control'] = 'private, max-age=60'
    return response

@app.route('/api/warehouse/update', methods=['POST'])
def update_quantity():
    auth_header = request.headers.get('X-Service-Auth', '')
    expected = hashlib.sha256(os.environ.get('SERVICE_SECRET', '').encode()).hexdigest()
    if not auth_header or auth_header != expected:
        return jsonify({"error": "unauthorized"}), 401

    data = request.get_json()
    if not data or 'part_id' not in data or 'delta' not in data:
        return jsonify({"error": "missing fields"}), 400

    db = get_db()
    try:
        db.execute(
            "UPDATE inventory SET quantity = quantity + ? WHERE part_id = ?",
            (int(data['delta']), data['part_id'])
        )
        db.commit()
        return jsonify({"status": "updated"})
    except (sqlite3.Error, ValueError) as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
